def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# Pairs found earlier
pairs = [
    (3, 797), (13, 787), (31, 769), (43, 757), (61, 739),
    (67, 733), (73, 727), (109, 691), (127, 673), (139, 661),
    (157, 643), (181, 619), (193, 607), (199, 601), (223, 577),
    (229, 571), (277, 523), (313, 487), (337, 463), (367, 433), (379, 421)
]

results = {}

for p, q in pairs:
    D = q - p
    possible_r = []

    # r must be odd and r > q. Max r is 797 since 800-r must be prime.
    # Start from q+2 (next odd number)
    start_r = q + 2
    end_r = 797

    for r in range(start_r, end_r + 1, 2):
        # Check condition 1: p+q-r = 800-r is prime
        P1 = 800 - r
        if not is_prime(P1):
            continue

        # Check condition 4: p+q+r = 800+r is prime
        P4 = 800 + r
        if not is_prime(P4):
            continue

        # Check condition 2: q+r-p = r + D is prime
        P2 = r + D
        if not is_prime(P2):
            continue

        # Check condition 3: r+p-q = r - D is prime
        P3 = r - D
        if not is_prime(P3):
            continue

        # All conditions met
        possible_r.append(r)

    results[(p, q)] = possible_r

# Find the maximum r overall
max_r_found = -1
for pair, rs in results.items():
    if rs:
        current_max_r = max(rs)
        if current_max_r > max_r_found:
            max_r_found = current_max_r

print("--- Detailed results (pairs and possible r values) ---")
for pair, rs in results.items():
    print(f"Pair {pair}: Possible r values found = {rs}")

print("\nMaximum possible value of r found in Case 1:")
print(max_r_found)
